import {frenchRoomsView,validFrenchRoomsWork,startFrenchRooms,setFrenchRoomsField,setFrenchRoomsSelection,showFrenchRoomsHelp,checkFrenchRooms,skipFrenchRooms,revealFrenchRoomsData,keepFrenchRooms} from './french-rooms-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(a,t)=>`<button type="button" class="secondary" ${a}>${esc(t)}</button>`;
function passage(w,key,text,meaning,title=''){const shown=w.help.includes(`${key}:meaning`);return `<section class="rooms-passage" id="rooms-passage-${esc(key.replaceAll(':','-'))}" tabindex="-1" data-room-audio-code="${esc(key)}:audio">${title?`<h3${['Nouveau message','Précision'].includes(title)?' lang="fr"':''}>${esc(title)}</h3>`:''}<p lang="fr">${esc(text)}</p><div class="rooms-actions">${btn(`data-rooms-help="${esc(key)}:meaning"`,'English meaning')}${hearButton(text,'Écouter en français','fr')}</div>${shown?`<p class="rooms-meaning" lang="en">${esc(meaning)}</p>`:''}</section>`;}
function floorplan(w){const current=w.source.rooms.map(r=>({...r,objects:r.objects.map(p=>[...p])}));if(w.source.id==='return'&&w.newData){const bedroom=current.find(r=>r.id==='chambre'),hall=current.find(r=>r.id==='entree');if(bedroom)bedroom.objects=bedroom.objects.filter(p=>p[0]!=='sac');if(hall)hall.objects.push(['sac','le sac · derrière la porte']);}const selected=current.flatMap(r=>[[r.id,r.name],...r.objects]).find(p=>p[0]===w.model.selected);return `<section class="rooms-plan"><h2 lang="fr">Le plan de la maison</h2><p lang="fr">Haut du plan ↑ · gauche ← · droite →</p><p>Directions follow the page. Rooms are shown as adjacent positions; this is a reading map, not a doorway plan. Tap an object or room to inspect its label.</p>${w.source.id==='return'&&w.newData?'<p lang="fr" class="rooms-new-label">Nouveau message : le sac a changé de place.</p>':''}<div class="rooms-grid">${current.map(r=>`<section class="rooms-room rooms-${esc(r.id)}" lang="fr" aria-label="${esc(r.name)}"><h3>${btn(`data-rooms-select="${esc(r.id)}" aria-pressed="${w.model.selected===r.id}"`,r.name)}</h3><div class="rooms-objects" lang="fr">${r.objects.map(p=>btn(`data-rooms-select="${esc(p[0])}" data-room-object="${esc(p[0])}" aria-pressed="${w.model.selected===p[0]}"`,p[1])).join('')}</div></section>`).join('')}</div><p class="rooms-selected" aria-live="polite" lang="fr">${selected?`Choix sur le plan : ${esc(selected[1])}`:'Choisis une pièce ou un objet.'}</p><p>The plan supports the questions. Selecting a map label is exploration; use the supplied choices to record a response.</p></section>`;}
function task(w,q){const last=w.checks.filter(c=>c.itemId===q.id).at(-1),blocked=!!w.source.newMessage&&q===w.source.items[1]&&!w.newData;return `<section class="rooms-task" id="rooms-item-${esc(q.id)}" tabindex="-1" data-rooms-item="${esc(q.id)}">${passage(w,q.id,q.prompt,q.meaning,'Question')} ${w.help.includes(`${q.id}:meaning`)?`<ul lang="en">${q.choices.map(a=>`<li><span lang="fr">${esc(a.text)}</span> — <span lang="en">${esc(a.meaning)}</span></li>`).join('')}</ul>`:''}${blocked?'<p>Open the new message first. Other lessons remain open.</p>':`<fieldset lang="fr"><legend>Ton choix</legend>${q.choices.map(a=>`<label><input type="radio" name="rooms-${esc(q.id)}" data-rooms-field="${esc(q.id)}" value="${esc(a.id)}" ${w.drafts[q.id]===a.id?'checked':''}>${esc(a.text)}</label>`).join('')}</fieldset>${btn(`data-rooms-check="${esc(q.id)}"`,'Check this choice')}`}${last?`<p class="rooms-feedback" lang="fr" role="status">${esc(last.feedback)} Dernier choix : ${esc(q.choices.find(c=>c.id===last.raw)?.text)}</p>`:''}<div class="rooms-actions">${['guided','hint','example'].map(k=>btn(`data-rooms-help="${esc(q.id)}:${k}"`,{guided:'Guided case',hint:'Hint',example:'Different example'}[k])).join('')}${btn(`data-rooms-skip="${esc(q.id)}"`,w.skips.includes(q.id)?'Skipped · return whenever you like':'Skip for now')}</div>${['guided','hint','example'].filter(k=>w.help.includes(`${q.id}:${k}`)).map(k=>passage(w,`${q.id}:${k}`,q[k],q[`${k}Meaning`],{guided:'Guided case',hint:'Hint',example:'Different example'}[k])).join('')}</section>`;}
function originalWriting(w){return `<section class="rooms-writing"><h2>Your message · human-read, ungraded</h2>${passage(w,'writing',w.source.writing,'Write a short message: a recent action and a plan. A person reads your words; there is no automatic grade.')}<label>Your original French message<textarea lang="fr" maxlength="1200" rows="4" data-rooms-field="explanation">
${esc(w.drafts.explanation)}</textarea></label>${btn('data-rooms-keep','Keep original message')}${w.firstKept?`<details><summary>First kept original</summary><p lang="fr">${esc(w.firstKept.drafts.explanation)||'(blank)'}</p></details>`:''}</section>`;}
function revisedWriting(w){return w.newData&&w.source.writing?`<section class="rooms-writing"><label>Revise your French message after the new location<textarea lang="fr" maxlength="1200" rows="4" data-rooms-field="revision">
${esc(w.drafts.revision)}</textarea></label>${btn('data-rooms-keep','Keep revision')}<p>Original and revised words stay separate. A grown-up can read them with you; there is no automatic language score.</p>${w.kept?'<p>Latest explicitly kept version retained.</p>':''}</section>`:'';}
export function frenchRoomsPage(state,requestedId){const v=frenchRoomsView(state),requested=v.lessons.find(l=>l.id===requestedId),w=requestedId&&requestedId!==state.frenchRooms?.currentId?null:v.work;return `<div class="rooms-page" data-rooms-root lang="en"><header><a class="back" href="#pathways">Choose a subject</a><p>French · four connected lessons</p><h1 id="rooms-heading" tabindex="-1" lang="fr">Les pièces et les projets</h1><p>Read a house plan, ask a precise question, then send and revise a short message. English meanings and local French speech are optional support. Every lesson stays open.</p></header>${v.status==='unavailable'?'<p>This saved format is retained unchanged. Other places remain open.</p><a href="#notes">Open your notes</a>':`<nav class="rooms-lessons" lang="fr" aria-label="Leçons de français">${v.lessons.map(l=>l.unreadable?`<p>${esc(l.title)}: earlier work retained; this lesson cannot be edited here.</p>`:btn(`data-rooms-start="${esc(l.id)}" aria-pressed="${w?.source.id===l.id}"`,l.title)).join('')}</nav>${requested&&!w&&!requested.unreadable?`<section><h2 lang="fr">${esc(requested.title)}</h2><p>Open this lesson explicitly. Your waiting lesson and drafts are retained.</p>${btn(`data-rooms-start="${esc(requested.id)}"`,'Start or continue this lesson')}</section>`:''}${w?`<article><h2 lang="fr">${esc(w.source.title)}</h2>${w.source.id==='return'?'<p>Imagine you are sending the first supplied message. The later message is a reply from someone else in the house.</p>':''}${passage(w,'intro',w.source.intro,w.source.meaning)}${passage(w,'teach',w.source.teach,w.source.teachMeaning,'Learn')}${floorplan(w)}${w.source.items.map((q,i)=>`${i===1&&w.source.newMessage?`${w.source.writing?originalWriting(w):''}<section class="rooms-new">${btn('data-rooms-new',w.source.id==='clarify'?'Read the clarification':'Read the new return message')}${w.newData?passage(w,'new',w.source.newMessage,w.source.newMeaning,w.source.id==='clarify'?'Précision':'Nouveau message'):''}</section>`:''}${task(w,q)}`).join('')}${revisedWriting(w)}</article>`:!requested?'<p>Choose any lesson to start or continue. No lesson is locked.</p>':''}`}<p id="rooms-status" role="status" aria-live="polite" tabindex="-1"></p><footer><a href="#french">Other French stories</a><a href="#notes">Grown-up notes</a></footer></div>`;}
export function frenchRoomsNotes(state){if(!Object.hasOwn(state,'frenchRooms'))return '';const v=frenchRoomsView(state);return `<details class="panel"><summary>Les pièces et les projets · supported French practice</summary><p>Frozen passages, plan, supplied choices and requested support remain separate from original human-read writing. Meaning requests and audio requests do not establish independent comprehension or listening; local speech is not native audio and has no fluency claim.</p>${v.status==='unavailable'?'<p>Earlier format retained unchanged.</p>':Object.entries(state.frenchRooms.lessons).map(([k,w])=>`<p>${esc(validFrenchRoomsWork(w)?w.source.title:k)}: ${validFrenchRoomsWork(w)?`${w.checks.length} recent checks, ${w.skips.length} skips; meaning/audio requests ${w.help.filter(h=>h.endsWith(':meaning')||h.endsWith(':audio')).length}; first kept ${w.firstKept?'yes':'no'}, latest kept ${w.kept?'yes':'no'}.`:'earlier unreadable lesson retained.'}</p>`).join('')}<details><summary>Exact source, plan, writing, support and checks</summary><pre>${esc(JSON.stringify(state.frenchRooms,null,2))}</pre></details></details>`;}
export function bindFrenchRooms(state,{save,render,focus,canExport,explorerId,isActive,entryLesson}={}){const root=document.querySelector('[data-rooms-root]');if(!root)return;const owner=explorerId?.(),route=location.hash,o={canExport};const dirtyFields=new Set();const live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&location.hash===route&&(!isActive||isActive())&&explorerId?.()===owner;const say=t=>{const e=root.querySelector('#rooms-status');if(e)e.textContent=t;};const fail=()=>say('This change could not be saved safely. Earlier work is unchanged. Keep or copy unsaved words before leaving.');const redraw=(msg='',target='#rooms-heading')=>{stopSpeech();save?.();render?.();focus?.(target);const e=document.querySelector('#rooms-status');if(e)e.textContent=msg;};const click=(selector,fn)=>root.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(!live(b))return;if(dirtyFields.size)return fail();fn(b);}));
 // Capture runs before the existing speech listener; support is committed before playback.
 root.addEventListener('click',e=>{const b=e.target.closest?.('[data-speak]');if(!b)return;if(!live(b)||dirtyFields.size){e.preventDefault();e.stopImmediatePropagation();return fail();}const code=b.closest('[data-room-audio-code]')?.dataset.roomAudioCode;if(!code||!showFrenchRoomsHelp(state,code,o)){e.preventDefault();e.stopImmediatePropagation();return fail();}save?.();say('French audio requested. Playback depends on an available local French voice.');},true);
 click('[data-rooms-start]',b=>{if(!startFrenchRooms(state,b.dataset.roomsStart,o))return fail();if((entryLesson||route.split('/')[2])&&b.dataset.roomsStart!==(entryLesson||route.split('/')[2]))location.hash='#learn/french/'+b.dataset.roomsStart;redraw();});
 root.querySelectorAll('[data-rooms-field]').forEach(e=>e.addEventListener(e.type==='radio'?'change':'input',()=>{if(!live(e))return;const ok=setFrenchRoomsField(state,e.dataset.roomsField,e.value,o);if(ok)dirtyFields.delete(e.dataset.roomsField);else dirtyFields.add(e.dataset.roomsField);if(!ok)return fail();save?.();say('Draft saved.');}));
 click('[data-rooms-select]',b=>setFrenchRoomsSelection(state,b.dataset.roomsSelect,o)?redraw('Map label selected.',`[data-rooms-select="${b.dataset.roomsSelect}"]`):fail());
 click('[data-rooms-help]',b=>{const code=b.dataset.roomsHelp,item=code.split(':')[0],target=frenchRoomsView(state).work?.source.items.some(q=>q.id===item)?`#rooms-item-${item}`:`#rooms-passage-${code.split(':').slice(0,-1).join('-')}`;showFrenchRoomsHelp(state,code,o)?redraw('Requested support opened.',target):fail();});
 click('[data-rooms-check]',b=>{if(!frenchRoomsView(state).work?.drafts[b.dataset.roomsCheck])return say('Choose a response first, or skip for now.');const r=checkFrenchRooms(state,b.dataset.roomsCheck,o);r?redraw(r.outcome==='match'?'Fits this supplied message.':'Compare the message and plan again.',`#rooms-item-${b.dataset.roomsCheck}`):fail();});
 click('[data-rooms-skip]',b=>skipFrenchRooms(state,b.dataset.roomsSkip,o)?redraw('Skipped for now. Return whenever you like.',`#rooms-item-${b.dataset.roomsSkip}`):fail());
 click('[data-rooms-new]',()=>revealFrenchRoomsData(state,o)?redraw('New message shown; original retained.','#rooms-status'):fail());
 click('[data-rooms-keep]',()=>keepFrenchRooms(state,o)?redraw('Exact version kept without a prose grade.','#rooms-status'):fail());
}
